(()=>{
const tree=document.querySelector('.nav-tree'),otherNames=['Configurações'],other=tree?.querySelector('details[data-menu-name="Configurações"]');if(!tree||!other)return;
const members=[...tree.children],others=members.filter(n=>otherNames.includes(n.dataset.menuName)),management=members.filter(n=>!others.includes(n));
const key='cicluz-sidebar-sections-v1';let state={};try{state=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}
const calendar='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M7 15h3M14 15h3"/></svg>';
const agenda=document.createElement('details');agenda.className='agenda-menu-item';agenda.dataset.menuName='Agenda/Atividades';agenda.innerHTML='<summary title="Agenda · Atividades"><span class="menu-icon-circle" style="color:#7c3aed">'+calendar+'</span><span class="menu-name"><span>Agenda</span><small>Atividades</small></span></summary><div class="children"></div>';other.before(agenda);agenda.querySelector('summary').addEventListener('click',e=>{const side=document.querySelector('.side');if(side?.classList.contains('collapsed')){e.preventDefault();document.getElementById('toggleMenu').click();agenda.open=true}});
for(const [label,lista] of [['Lançamentos','lista-diretor-operacoes']]){const button=document.createElement('button');button.type='button';button.innerHTML='<span class="icone-sub" aria-hidden="true"><svg viewBox="0 0 24 24">'+subIcone[label]+'</svg></span>'+label;button.onclick=()=>{document.querySelectorAll('.nav button').forEach(n=>n.classList.remove('active'));button.classList.add('active');window.CicluzAgenda.abrir(lista)};agenda.querySelector('.children').append(button)}
{const pedidos=document.createElement('button');pedidos.type='button';pedidos.innerHTML='<span class="icone-sub" aria-hidden="true"><svg viewBox="0 0 24 24">'+subIcone['Lançamentos']+'</svg></span>MER - Agenda de Pedidos';pedidos.onclick=()=>{document.querySelectorAll('.nav button').forEach(n=>n.classList.remove('active'));pedidos.classList.add('active');document.querySelectorAll('.view').forEach(v=>v.classList.remove('show'));CicluzCompras.abrir('agendamento')};agenda.querySelector('.children').append(pedidos)}
{const producao=document.createElement('button');producao.type='button';producao.innerHTML='<span class="icone-sub" aria-hidden="true"><svg viewBox="0 0 24 24">'+subIcone['Lançamentos']+'</svg></span>MER - Agenda de Produção';producao.onclick=()=>{document.querySelectorAll('.nav button').forEach(n=>n.classList.remove('active'));producao.classList.add('active');document.querySelectorAll('.view').forEach(v=>v.classList.remove('show'));CicluzProducao.abrir('agendamento')};agenda.querySelector('.children').append(producao)}
/* Entrevistas e Avaliações: itens diretos, na mesma região da Agenda. Abrem as telas que já existem (showInterviews) e o módulo novo (showAvaliacoes). */
const direct=(name,sub,icon,open)=>{const d=document.createElement('details');d.className='agenda-menu-item';d.dataset.menuName=name;d.innerHTML='<summary title="'+name+'"><span class="menu-icon-circle" style="color:#7c3aed"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+icon+'"/></svg></span><span class="menu-name"><span>'+name+'</span><small>'+sub+'</small></span></summary>';
 d.querySelector('summary').addEventListener('click',e=>{e.preventDefault();const side=document.querySelector('.side');if(side?.classList.contains('collapsed'))document.getElementById('toggleMenu').click();document.querySelectorAll('.nav button').forEach(n=>n.classList.remove('active'));open();document.dispatchEvent(new Event('cicluz-close-menu'))});return d};
const entrevistas=direct('Entrevistas','Candidatos','M4 5h16v11H9l-5 4zM8 9h8M8 12h5',()=>window.showEntrevistas?.());
/* Avaliações: grupo que expande no menu, igual ao da Agenda, com os submenus como botões. */
const avaliacoes=document.createElement('details');avaliacoes.className='agenda-menu-item';avaliacoes.dataset.menuName='Avaliações';
avaliacoes.innerHTML='<summary title="Avaliações"><span class="menu-icon-circle" style="color:#7c3aed"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 4h6v3H9zM7 5H5v16h14V5h-2M9 14l2 2 4-4"/></svg></span><span class="menu-name"><span>Avaliações</span><small>Pessoas e equipes</small></span></summary><div class="children"></div>';
avaliacoes.querySelector('summary').addEventListener('click',()=>{const side=document.querySelector('.side');if(side?.classList.contains('collapsed')){document.getElementById('toggleMenu').click();avaliacoes.open=true}});
for(const [key,label] of [['individual','Avaliação Individual'],['equipe','Avaliação em Equipe'],['geral','Avaliação Geral'],['vinculos','Vínculos do setor'],['salvas','Avaliações salvas']]){const b=document.createElement('button');b.type='button';b.innerHTML='<span class="icone-sub" aria-hidden="true"><svg viewBox="0 0 24 24">'+subIcone['Lançamentos']+'</svg></span>'+label;
 b.onclick=()=>{document.querySelectorAll('.nav button').forEach(n=>n.classList.remove('active'));b.classList.add('active');window.showAvaliacoes?.(key);document.dispatchEvent(new Event('cicluz-close-menu'))};avaliacoes.querySelector('.children').append(b)}
agenda.after(entrevistas);entrevistas.after(avaliacoes);
tree.classList.add('sidebar-sectioned');
function section(id,label,nodes,before){const b=document.createElement('button');b.type='button';b.className='sidebar-section-toggle';b.dataset.section=id;b.innerHTML='<span>'+label+'</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 9 7 7 7-7"/></svg>';before.before(b);function update(){const open=state[id]!==false;b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',(open?'Recolher ':'Expandir ')+label);nodes.forEach(n=>n.classList.toggle('sidebar-section-hidden',!open))}b.onclick=()=>{state[id]=state[id]===false;update();try{localStorage.setItem(key,JSON.stringify(state))}catch(e){}};update()}
section('management','GESTÃO',management,tree.firstElementChild);section('agenda','AGENDA',[agenda,entrevistas,avaliacoes],agenda);section('others','CONFIGURAÇÕES',others,other);
})();
